    def __init__(self):
        super().__init__()
        self.inventory = 0
        self.cash = 0
        self._orders = {}
        self._distribution_time=self._distribution_mid=None
        self._distribution_seen={}
        self._distribution_fresh_count=[0.0]*8
        self._distribution_fresh_value=[0.0]*8
        self._distribution_frame=((),())
        self._toxic_buy=self._toxic_sell=False
        self._fill_buyprice=self._fill_sellprice=None
        self._tree_time=None
        self._tree_last_mid=None
        self._tree_cached=0.0
        self._vol_next=None
        self._vol_sample_mid=self._vol_previous_mid=None
        self._vol_variance=1.0
        self._vol_sigma=1.0
        self._vol_samples=0
        self._modify_pending={}
        self._upper_target=50
        self._lower_target=-50
        self._target_updated=None
        self._target_prediction=0.0
